(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(my*0.03+t*0.15)*8 + Math.cos(mx*0.025-t*0.1)*6;
  const w2y = Math.cos(mx*0.028-t*0.12)*8 + Math.sin(my*0.022+t*0.18)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+2)*55,0.11,2.1],
    [400+Math.cos(t*0.55+1)*60,220+Math.sin(t*0.75+4)*50,0.085,1.8]
  ];
  let aS=0,iS=0,harm=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    harm+=Math.sin(d*f*0.5-t*sp*0.3+0.785);
  }
  const act=aS/8,inh=iS/8,har=harm/8;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.08+Math.sin(sy*0.06+t)*2+t*0.5)*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*5+t*0.8);
  const spiral=(sp1+sp2+sp3)*0.27;
  const rd1=act-inh*0.7+bg*0.3+spiral;
  const rd2=har*0.4+Math.sin(act*inh*2)*0.3;
  const reaction=Math.tanh((rd1+rd2)*2.0);
  const c1=Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const c2=Math.sin((sx+sy)*0.1+t)*0.5;
  const c3=Math.sin(sx*0.2-sy*0.1+t*0.3)*0.3;
  const cell=Math.tanh((c1+c2+c3)*1.5)*0.25;
  const moire=Math.sin(sx*0.3)*Math.sin(sy*0.3)*Math.sin((sx+sy)*0.15-t*0.5)*0.15;
  const blend=reaction*0.6+cell*0.2+moire*0.1+spiral*0.1;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,88],[18,85,115],[25,135,130],[80,165,120],[180,185,80],[210,160,65],[215,110,60],[180,60,55],[130,35,60],[70,20,55],[25,15,50],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge=1.0+Math.max(0,Math.abs(reaction)-0.65)*0.5;
  const glow=Math.max(0,reaction-0.5)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*255)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*180)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*100)|0)
  ];
}
